mapper.sql:
where c.use_yn = 'Y'
  and c.cal_date between #{from} and #{to}
  and (c.plant_cd is null or c.plant_cd = #{plantCd})

mapper.update:
update mst_work_cal
   set day_type = #{dayType}, reason = #{reason}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where cal_id = #{id} and row_ver = #{rowVer} and use_yn = 'Y'

update mst_work_cal
   set use_yn = 'N', row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where cal_id = #{id} and row_ver = #{rowVer} and use_yn = 'Y'
